{
  "schemaVersion": "0.2",
  "slug": "search-bar",
  "name": "SearchBar",
  "family": "C",
  "status": "experimental",
  "purpose": "Search input with submit and clear controls inside a search landmark.",
  "scenarios": [
    "Filter a component catalog",
    "Search documentation",
    "Query a market listing"
  ],
  "props": {
    "value": {
      "type": "string",
      "required": true,
      "description": "Current query."
    },
    "onChange": {
      "type": "event",
      "required": true,
      "description": "Called with the query on edit."
    },
    "onSubmit": {
      "type": "event",
      "required": false,
      "description": "Called with the query on submit."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible label for the search field."
    },
    "placeholder": {
      "type": "string",
      "required": false,
      "description": "Input placeholder."
    },
    "clearLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible label for the clear control."
    },
    "submitLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible label for the submit control."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Idle search field."
    },
    {
      "name": "filled",
      "description": "Query present; clear control visible."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "page",
      "card",
      "form"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not auto-submit on every keystroke without debounce.",
    "Do not remove the text label in favor of placeholder-only naming."
  ],
  "a11y": {
    "role": "search",
    "keyboard": [
      "Enter submits",
      "Escape clears when filled"
    ],
    "focus": "Input, clear, and submit controls are in tab order.",
    "labeling": "Search landmark plus field label name the control.",
    "wcag": [
      "1.3.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Full width at all breakpoints.",
    "breakpoints": {
      "compact": "Full width.",
      "medium": "Full width.",
      "large": "Full width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "search-bar",
    "states": [
      "default",
      "filled"
    ],
    "intents": [
      "search-select"
    ]
  }
}

import { useRef } from 'react'
import '../input/styles.css'
import './styles.css'

export interface SearchBarProps {
  value: string
  onChange: (value: string) => void
  onSubmit?: (value: string) => void
  label: string
  placeholder?: string
  clearLabel?: string
  submitLabel?: string
  className?: string
}

export function SearchBar({
  value,
  onChange,
  onSubmit,
  label,
  placeholder = 'Search',
  clearLabel = 'Clear',
  submitLabel = 'Submit search',
  className,
}: SearchBarProps) {
  const inputRef = useRef<HTMLInputElement>(null)
  const classes = ['cu-search-bar', className].filter(Boolean).join(' ')

  return (
    <form
      className={classes}
      role="search"
      aria-label={label}
      data-ai-role="search-bar" data-ai-intent="search-select"
      data-ai-state={value.length > 0 ? 'filled' : 'default'}
      onSubmit={(event) => {
        event.preventDefault()
        onSubmit?.(value)
      }}
    >
      <label className="cu-search-bar__label">
        <span className="cu-search-bar__label-text">{label}</span>
        <input
          ref={inputRef}
          className="cu-input"
          type="search"
          value={value}
          placeholder={placeholder}
          onChange={(event) => onChange(event.currentTarget.value)}
          onKeyDown={(event) => {
            if (event.key === 'Escape' && value.length > 0) {
              event.preventDefault()
              onChange('')
            }
          }}
        />
      </label>
      {value.length > 0 ? (
        <button
          type="button"
          className="cu-search-bar__clear"
          aria-label={clearLabel}
          onClick={() => {
            onChange('')
            inputRef.current?.focus()
          }}
        >
          ×
        </button>
      ) : null}
      <button type="submit" className="cu-search-bar__submit" aria-label={submitLabel}>
        <span aria-hidden="true">⌕</span>
      </button>
    </form>
  )
}

.cu-search-bar {
  display: flex;
  align-items: flex-end;
  gap: var(--cu-space-1);
  color: var(--cu-color-fg-default);
}

.cu-search-bar__label {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: calc(var(--cu-space-1) / 2);
}

.cu-search-bar__label-text {
  font-size: 0.875em;
}

.cu-search-bar__clear,
.cu-search-bar__submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--cu-space-3);
  block-size: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.cu-search-bar__submit {
  background: var(--cu-color-palette-brand);
  border-color: var(--cu-color-palette-brand);
  color: var(--cu-color-fg-inverse);
}

.cu-search-bar__clear:focus-visible,
.cu-search-bar__submit:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}
